<template><PageShell title="排班管理" description="周排班模板＋指定日期覆盖，并可按月调整应出勤天数和月休额度。" @refresh="load">
  <el-tabs v-model="tab"><el-tab-pane label="周排班模板" name="weekly"><div class="toolbar"><el-button type="primary" :disabled="!store.employeeId" @click="saveWeek">保存本周模板</el-button></div><el-empty v-if="!store.employeeId" description="请先选择员工"/><el-table v-else :data="weekRows"><el-table-column prop="label" label="星期"/><el-table-column label="工作日"><template #default="{row}"><el-switch v-model="row.isWorkday"/></template></el-table-column><el-table-column label="排班工时（分钟）"><template #default="{row}"><el-input-number v-model="row.scheduledMinutes" :min="0" :max="1440" :disabled="!row.isWorkday"/></template></el-table-column></el-table></el-tab-pane>
  <el-tab-pane label="临时调班" name="override"><div class="toolbar"><el-date-picker v-model="overrideForm.date" value-format="YYYY-MM-DD"/><el-switch v-model="overrideForm.isWorkday" active-text="上班" inactive-text="休息"/><el-input-number v-model="overrideForm.scheduledMinutes" :min="0" :max="1440"/><el-input v-model="overrideForm.remark" placeholder="调班备注" style="width:200px"/><el-button type="primary" @click="saveOverride">新增调班</el-button></div><el-table :data="store.overrides" empty-text="暂无临时调班"><el-table-column prop="date" label="日期"/><el-table-column label="类型"><template #default="{row}">{{row.isWorkday?'上班':'休息'}}</template></el-table-column><el-table-column prop="scheduledMinutes" label="分钟"/><el-table-column prop="remark" label="备注"/><el-table-column label="操作"><template #default="{row}"><el-button link type="danger" @click="removeOverride(row.id)">删除</el-button></template></el-table-column></el-table></el-tab-pane>
  <el-tab-pane label="月度设置" name="month"><div class="toolbar"><el-input-number v-model="monthForm.scheduledWorkDays" :min="0"/><span>应出勤天</span><el-input-number v-model="monthForm.restQuotaDays" :min="0"/><span>月休额度</span><el-button type="primary" @click="saveMonth">保存</el-button></div><el-table :data="store.monthSettings"><el-table-column label="员工"><template #default="{row}">{{nameOf(row.employeeId)}}</template></el-table-column><el-table-column prop="month" label="月份"/><el-table-column prop="scheduledWorkDays" label="应出勤天"/><el-table-column prop="restQuotaDays" label="月休额度"/></el-table></el-tab-pane></el-tabs>
</PageShell></template>
<script setup lang="ts">import { computed,onMounted,reactive,ref,watch } from 'vue';import dayjs from 'dayjs';import {ElMessage} from 'element-plus';import PageShell from './EmployeeAttendancePageShell.vue';import {useEmployeeAttendanceStore} from '@/stores/employeeAttendance';import * as api from '@/api/employeeAttendance'
const store=useEmployeeAttendanceStore(),tab=ref('weekly'),labels=['周日','周一','周二','周三','周四','周五','周六'];const overrideForm=reactive({date:dayjs().format('YYYY-MM-DD'),isWorkday:true,scheduledMinutes:480,remark:''}),monthForm=reactive({scheduledWorkDays:22,restQuotaDays:4});const weekRows=computed(()=>labels.map((label,weekday)=>{const row=store.weeklySchedules.find(item=>item.weekday===weekday);return{id:row?.id,label,weekday,isWorkday:row?.isWorkday??(weekday>0&&weekday<6),scheduledMinutes:row?.scheduledMinutes??(weekday>0&&weekday<6?480:0)}}));function nameOf(id:string){return store.employees.find(row=>row.id===id)?.name||'-'}async function load(){await store.loadSchedules().catch(()=>undefined)}async function saveWeek(){await store.run(()=>Promise.all(weekRows.value.map(row=>api.saveWeeklySchedule({employeeId:store.employeeId,weekday:row.weekday,isWorkday:row.isWorkday,scheduledMinutes:row.isWorkday?row.scheduledMinutes:0},row.id))),true).then(()=>{ElMessage.success('周排班已保存');return load()}).catch(()=>undefined)}async function saveOverride(){if(!store.employeeId)return ElMessage.warning('请选择员工');await store.run(()=>api.saveDateOverride({employeeId:store.employeeId,...overrideForm}),true).then(load).catch(()=>undefined)}async function removeOverride(id:string){await api.deleteDateOverride(id);await load()}async function saveMonth(){if(!store.employeeId)return ElMessage.warning('请选择员工');await store.run(()=>api.saveMonthlySetting({employeeId:store.employeeId,month:store.month,...monthForm}),true).then(load).catch(()=>undefined)}watch(()=>store.employeeId,load);onMounted(load);
</script>
